using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class C02RefineAudit {
 static readonly Vector3 Origin=new Vector3(-22,-82,18);static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;static float Distance(Vector3 p,Vector3 a,Vector3 b){p.y=a.y=b.y=0;var d=b-a;return Vector3.Distance(p,a+d*Mathf.Clamp01(Vector3.Dot(p-a,d)/d.sqrMagnitude));}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("C02_Security_Art");var repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var o=repo+"/Docs/검수/2026-11-08_C02_Refine/";var before=JObject.Parse(File.ReadAllText(o+"before.json"));var meshes=group.GetComponentsInChildren<MeshFilter>().Select(m=>m.sharedMesh).Distinct().ToArray();var mr=new List<object>();int degenerate=0,triangles=0;
 foreach(var m in meshes){var v=m.vertices;var t=m.triangles;int bad=0;for(int i=0;i<t.Length;i+=3)if(Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]).sqrMagnitude<1e-14f)bad++;mr.Add(new{m.name,triangles=t.Length/3,degenerate=bad});degenerate+=bad;triangles+=t.Length/3;}
 var current=JArray.Parse(JsonConvert.SerializeObject(root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}).ToArray()));var changes=new List<string>();foreach(var item in before["hierarchy"]){string path=(string)item["path"];if(!current.Any(j=>JToken.DeepEquals(j,item)))changes.Add(path);}
 var lights=JArray.Parse(JsonConvert.SerializeObject(root.GetComponentsInChildren<Light>(true).Select(l=>new{path=P(l.transform),enabled=l.enabled,active=l.gameObject.activeInHierarchy,position=V(l.transform.position),rotation=V(l.transform.eulerAngles),l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()}).ToArray()));var lightChanges=before["lights"].Where(j=>!lights.Any(k=>JToken.DeepEquals(j,k))).Select(j=>(string)j["path"]).ToArray();
 var doors=new[]{new Vector3(1.503721f,0,-6.014883f),new Vector3(-5.644272f,0,2.565578f),new Vector3(6.19143f,0,.325865f)};var paths=new List<Vector3[]>();foreach(var d in doors)paths.Add(new[]{Vector3.zero,d+d.normalized*1.2f});paths.Add(new[]{doors[2],new Vector3(32.807187f,0,1.726694f)});foreach(var t in new[]{new Vector3(-1.25f,0,1.82f),new Vector3(1.25f,0,1.82f),new Vector3(2.8f,0,1.9f),new Vector3(-3.8f,0,-1.5f),new Vector3(3.5f,0,-2.2f)})paths.Add(new[]{Vector3.zero,t});paths.Add(new[]{Vector3.zero,new Vector3(0,0,-4.2f)});paths.Add(new[]{new Vector3(0,0,-4.2f),new Vector3(-2.3f,0,-4.2f)});paths.Add(new[]{new Vector3(-2.3f,0,-4.2f),new Vector3(-2.7f,0,-3.85f)});Physics.SyncTransforms();int samples=0;var blocked=new List<object>();var noFloor=new List<object>();for(int route=0;route<paths.Count;route++){var a=paths[route][0];var b=paths[route][1];var right=Vector3.Cross(Vector3.up,(b-a).normalized);var lanes=route<4?new[]{-.60f,0,.60f}:new[]{0f};foreach(float side in lanes){int n=Mathf.CeilToInt(Vector3.Distance(a,b)/.10f);for(int i=0;i<=n;i++){samples++;var p=Origin+Vector3.Lerp(a,b,(float)i/n)+right*side;bool ground=Physics.RaycastAll(p+Vector3.up*.22f,Vector3.down,.5f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root));if(!ground)noFloor.Add(new{route,side,point=V(p)});var hits=Physics.OverlapCapsule(p+Vector3.up*.37f,p+Vector3.up*1.50f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Length>0)blocked.Add(new{route,side,point=V(p),hits=hits.Select(c=>P(c.transform)).ToArray()});}}}
 float minClear=float.MaxValue;int overlaps=0;var labels=group.Cast<Transform>().Where(t=>t.name.StartsWith("SC_Destination")).ToArray();var guideMeshes=root.Find("Facility_Floor_Guidance_R1").GetComponentsInChildren<MeshFilter>().Concat(new[]{group.Find("SC_R1_T05_ToC04").GetComponent<MeshFilter>()});foreach(var mf in guideMeshes){var vs=mf.sharedMesh.vertices;var tris=mf.sharedMesh.triangles;for(int i=0;i<tris.Length;i+=3){var a=mf.transform.TransformPoint(vs[tris[i]]);var b=mf.transform.TransformPoint(vs[tris[i+1]]);var c=mf.transform.TransformPoint(vs[tris[i+2]]);int n=Mathf.Max(1,Mathf.CeilToInt(Mathf.Max(Vector3.Distance(a,b),Vector3.Distance(a,c))/.025f));for(int k=0;k<=n;k++)foreach(var p in new[]{Vector3.Lerp(a,b,(float)k/n),Vector3.Lerp(a,c,(float)k/n),Vector3.Lerp(b,c,(float)k/n)})foreach(var label in labels){var v=label.InverseTransformPoint(p);float dx=Mathf.Max(0,Mathf.Abs(v.x)-.3f),dz=Mathf.Max(0,Mathf.Abs(v.z)-.7f);float d=Mathf.Sqrt(dx*dx+dz*dz);minClear=Mathf.Min(minClear,d);if(d<.001f)overlaps++;}}}
 var rr=group.GetComponentsInChildren<Renderer>();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var result=new{scene=s.path,dirty=s.isDirty,meshReport=mr,uniqueMeshes=meshes.Length,uniqueTriangles=triangles,degenerateTriangles=degenerate,missingMaterials=rr.Sum(r=>r.sharedMaterials.Count(m=>!m||!m.shader)),samples,blocked,missingFloor=noFloor,protectedTransformChanges=changes,lightCount=lights.Count,lightChanges,newBehaviours=group.GetComponentsInChildren<MonoBehaviour>(true).Length,newLights=group.GetComponentsInChildren<Light>(true).Length,labelGuideMinClearance=minClear,labelGuideOverlapSamples=overlaps,playerPosition=V(player.transform.position),playerRotation=V(player.transform.eulerAngles),runInBackground=PlayerSettings.runInBackground};File.WriteAllText(o+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{uniqueMeshes=meshes.Length,uniqueTriangles=triangles,degenerate,missingMaterials=result.missingMaterials,samples,blocked=blocked.Count,noFloor=noFloor.Count,protectedChanges=changes.Count,lightChanges,labelGuideMinClearance=minClear,overlaps};}
}
